export function useStoredThemes() {
  const { getStoredThemes } = useService(ThemeServiceKey)
  const storedThemes = ref<StoredTheme[]>([])

  async function refresh() {
    storedThemes.value = await getStoredThemes()
  }

  onMounted(refresh)

  return {
    storedThemes,
    refresh }
}

